// Generated by sema from Action function definitions.
use crate::{FlowId, ParameterId, ScopeId, SemaContext, StructTagId, SymbolId};

pub fn assign_integer(
    ctx: &mut SemaContext,
    flow: FlowId,
    scope: ScopeId,
    name: &str,
    literal: &str,
) -> Result<SymbolId, &'static str> {
    let found = crate::sema_lib_gen::lookup_lexical(&*ctx, scope, name);
    if found.is_none() {
        return Err("undeclared identifier");
    }
    let target = ctx.option_symbol(found);
    if ctx.symbol_is_function(target) {
        return Err("not assignable");
    }
    let value = ctx.parse_integer(literal)?;
    ctx.record_integer_assignment(flow, target, value);
    ctx.flow_mark_initialized(flow, target);
    Ok(target)
}

pub fn bind(
    ctx: &mut SemaContext,
    scope: ScopeId,
    name: &str,
    symbol: SymbolId,
) -> Result<SymbolId, &'static str> {
    if crate::sema_lib_gen::contains_local(&*ctx, scope, name) {
        return Err("identifier already declared");
    }
    ctx.scope_insert(scope, name, symbol);
    Ok(symbol)
}

pub fn bind_parameters(
    ctx: &mut SemaContext,
    flow: FlowId,
    scope: ScopeId,
    parameters: &[ParameterId],
) -> Result<(), &'static str> {
    if !(crate::sema_lib_gen::unique_names(&*ctx, &parameters)) {
        return Err("duplicate parameter");
    }
    for parameter in parameters.iter().copied() {
        let name = ctx.copy_text(ctx.parameter_name(parameter));
        if crate::sema_lib_gen::contains_local(&*ctx, scope, name.as_str()) {
            return Err("identifier already declared");
        }
    }
    for parameter in parameters.iter().copied() {
        let name = ctx.copy_text(ctx.parameter_name(parameter));
        let symbol = crate::sema_lib_gen::declare_variable(&mut *ctx, flow, scope, name.as_str())?;
        ctx.flow_mark_initialized(flow, symbol);
    }
    Ok(())
}

pub fn bind_tag(
    ctx: &mut SemaContext,
    scope: ScopeId,
    name: &str,
    tag: StructTagId,
) -> Result<StructTagId, &'static str> {
    if ctx.scope_lookup_tag(scope, name).is_some() {
        return Err("tag already declared");
    }
    ctx.scope_insert_tag(scope, name, tag);
    Ok(tag)
}

pub fn contains_local(ctx: &SemaContext, scope: ScopeId, name: &str) -> bool {
    let found = ctx.scope_lookup(scope, name);
    found.is_some()
}

pub fn contains_name(ctx: &SemaContext, parameters: &[ParameterId], name: &str) -> bool {
    for parameter in parameters.iter().copied() {
        if ctx.parameter_name(parameter) == name {
            return true;
        }
    }
    false
}

pub fn declare_function(
    ctx: &mut SemaContext,
    scope: ScopeId,
    name: &str,
    signature: &str,
    definition: bool,
) -> Result<SymbolId, &'static str> {
    let existing = ctx.scope_lookup(scope, name);
    if existing.is_some() {
        let symbol = ctx.option_symbol(existing);
        if !ctx.symbol_is_function(symbol) {
            return Err("identifier already declared");
        }
        if ctx.function_signature(symbol) != signature {
            return Err("conflicting function declaration");
        }
        if definition {
            if ctx.function_is_defined(symbol) {
                return Err("function already defined");
            }
            ctx.mark_function_defined(symbol);
        }
        return Ok(symbol);
    }
    let symbol = ctx.fresh_function(scope, name, signature, definition);
    crate::sema_lib_gen::bind(&mut *ctx, scope, name, symbol)
}

pub fn declare_incomplete_struct(
    ctx: &mut SemaContext,
    scope: ScopeId,
    name: &str,
) -> Result<StructTagId, &'static str> {
    if ctx.scope_lookup_tag(scope, name).is_some() {
        return Err("tag already declared");
    }
    let tag = ctx.fresh_struct_tag(scope, name);
    crate::sema_lib_gen::bind_tag(&mut *ctx, scope, name, tag)
}

pub fn declare_variable(
    ctx: &mut SemaContext,
    flow: FlowId,
    scope: ScopeId,
    name: &str,
) -> Result<SymbolId, &'static str> {
    if crate::sema_lib_gen::contains_local(&*ctx, scope, name) {
        return Err("identifier already declared");
    }
    let symbol = ctx.fresh_variable(scope, name);
    let bound = crate::sema_lib_gen::bind(&mut *ctx, scope, name, symbol)?;
    ctx.flow_declare_variable(flow, bound);
    Ok(bound)
}

pub fn leave_scope(ctx: &mut SemaContext, flow: FlowId, scope: ScopeId) {
    for symbol in ctx.scope_symbols(scope) {
        ctx.flow_remove(flow, symbol);
    }
}

pub fn lookup_lexical(ctx: &SemaContext, scope: ScopeId, name: &str) -> Option<SymbolId> {
    for current in ctx.scope_chain(scope) {
        if crate::sema_lib_gen::contains_local(ctx, current, name) {
            return ctx.scope_lookup(current, name);
        }
    }
    None
}

pub fn lookup_tag_lexical(ctx: &SemaContext, scope: ScopeId, name: &str) -> Option<StructTagId> {
    for current in ctx.scope_chain(scope) {
        let tag = ctx.scope_lookup_tag(current, name);
        if tag.is_some() {
            return tag;
        }
    }
    None
}

pub fn merge_flow(ctx: &mut SemaContext, left: FlowId, right: FlowId) -> FlowId {
    let merged = ctx.flow_copy(left);
    for symbol in ctx.flow_symbols(left) {
        if !(ctx.flow_contains(right, symbol)) {
            ctx.flow_remove(merged, symbol);
        } else {
            let left_ready = ctx.flow_is_initialized(left, symbol);
            let right_ready = ctx.flow_is_initialized(right, symbol);
            if left_ready && right_ready {
                let left_zero = ctx.flow_is_zero_initialized(left, symbol);
                let right_zero = ctx.flow_is_zero_initialized(right, symbol);
                if left_zero && right_zero {
                    ctx.flow_mark_zero_initialized(merged, symbol);
                } else {
                    ctx.flow_mark_initialized(merged, symbol);
                }
            } else {
                ctx.flow_mark_uninitialized(merged, symbol);
            }
        }
    }
    merged
}

pub fn read_symbol(
    ctx: &SemaContext,
    flow: FlowId,
    symbol: SymbolId,
) -> Result<SymbolId, &'static str> {
    if ctx.symbol_is_function(symbol) {
        return Ok(symbol);
    }
    if !(ctx.flow_is_initialized(flow, symbol)) {
        return Err("uninitialized variable");
    }
    Ok(symbol)
}

pub fn unique_names(ctx: &SemaContext, parameters: &[ParameterId]) -> bool {
    for first in parameters.iter().copied() {
        for second in parameters.iter().copied() {
            if first != second && ctx.parameter_name(first) == ctx.parameter_name(second) {
                return false;
            }
        }
    }
    true
}
